// cspell:ignore cbbtc Cbbtc CBBTC

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import BigNumber from 'bignumber.js';
import { useIntl } from 'react-intl';

import { SizableText, Switch, XStack, useMedia } from '@onekeyhq/components';
import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import useAppNavigation from '@onekeyhq/kit/src/hooks/useAppNavigation';
import { usePromiseResult } from '@onekeyhq/kit/src/hooks/usePromiseResult';
import { useActiveAccount } from '@onekeyhq/kit/src/states/jotai/contexts/accountSelector';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import type { IBorrowReserveItem } from '@onekeyhq/shared/types/staking';

import { useToOnBoardingPage } from '../../Onboarding/hooks/useToOnBoardingPage';
import { EManagePositionType } from '../../Staking/pages/ManagePosition/hooks/useManagePage';
import {
  hasBorrowReservesForMarket,
  isBorrowReservesPending,
} from '../borrowDataStatus';
import { buildBorrowMarketKey } from '../borrowMarketKey';
import { useBorrowContext } from '../BorrowProvider';
import { BorrowNavigation } from '../borrowUtils';
import { BorrowTestIDs } from '../testIDs';

import { splitCbbtcAssets } from './borrowCbbtc.utils';
import {
  filterUnsupportedAaveNativeReserveAssets,
  hasPositiveBorrowBalance,
} from './borrowRepayPosition.utils';
import {
  ActionField,
  AmountField,
  AssetField,
  AssetWithAmountField,
  BORROW_TABLE_ACTION_COLUMN_COMPACT_WIDTH,
  BORROW_TABLE_ACTION_COLUMN_WIDTH,
  BORROW_TABLE_AMOUNT_COLUMN_MAX_WIDTH,
  BORROW_TABLE_AMOUNT_COLUMN_MIN_WIDTH,
  BORROW_TABLE_APY_COLUMN_MAX_WIDTH,
  BORROW_TABLE_APY_COLUMN_MIN_WIDTH,
  BORROW_TABLE_ASSET_COLUMN_MIN_WIDTH,
  BorrowAPYField,
  BorrowMoreToggle,
  BorrowTableList,
} from './BorrowTableList';
import { Card } from './Card';

type ISupplyAsset = IBorrowReserveItem['supply']['assets'][number];

export const SupplyCard = () => {
  const { reserves, market, borrowDataStatus, earnAccount } =
    useBorrowContext();
  const intl = useIntl();
  const navigation = useAppNavigation();
  const { activeAccount } = useActiveAccount({ num: 0 });
  const { gtMd, gtLg } = useMedia();
  const [showZeroBalance, setShowZeroBalance] = useState(true);
  const accountId = earnAccount.data?.account?.id || '';
  const walletId = earnAccount.data?.walletId || '';
  const indexedAccountId = earnAccount.data?.account?.indexedAccountId;
  const noConnectedWallet = useMemo(
    () =>
      activeAccount.ready &&
      !activeAccount.wallet?.id &&
      !activeAccount.account?.id &&
      !activeAccount.indexedAccount?.id,
    [
      activeAccount.ready,
      activeAccount.wallet?.id,
      activeAccount.account?.id,
      activeAccount.indexedAccount?.id,
    ],
  );
  const { result: accountNetworkNotSupported = false } = usePromiseResult(
    async () => {
      if (!market?.networkId) return false;
      if (!activeAccount.wallet?.id && !activeAccount.account?.id) return false;

      const result =
        await backgroundApiProxy.serviceAccount.checkAccountNetworkNotSupported(
          {
            walletId: activeAccount.wallet?.id,
            accountId: activeAccount.account?.id,
            accountImpl: activeAccount.account?.impl,
            activeNetworkId: market.networkId,
          },
        );

      return !!result?.networkImpl;
    },
    [
      activeAccount.account?.id,
      activeAccount.account?.impl,
      activeAccount.wallet?.id,
      market?.networkId,
    ],
    { initResult: false },
  );

  const toOnBoardingPage = useToOnBoardingPage();

  // Use ref to hold the latest value of noConnectedWallet.
  // This avoids stale closure issues caused by TableList's custom memo
  // comparator (compareTableListProps) which uses stringify for columns
  // (losing function references) and skips onPressRow comparison.
  const noConnectedWalletRef = useRef(noConnectedWallet);
  noConnectedWalletRef.current = noConnectedWallet;

  const handleManageSupply = useCallback(
    (item: ISupplyAsset) => {
      // Read from ref to avoid stale closure from TableList memo caching
      if (noConnectedWalletRef.current) {
        void toOnBoardingPage();
        return;
      }
      if (!market) return;

      BorrowNavigation.pushToBorrowManagePosition(navigation, {
        accountId,
        networkId: market.networkId,
        provider: market.provider,
        marketAddress: market.marketAddress,
        reserveAddress: item.reserveAddress,
        symbol: item.token.symbol,
        providerLogoURI: market.logoURI,
        logoURI: item.token.logoURI,
        type: EManagePositionType.Supply,
      });
    },
    [noConnectedWalletRef, toOnBoardingPage, navigation, market, accountId],
  );

  const handlePressRow = useCallback(
    (item: ISupplyAsset) => {
      if (!market) return;
      if (gtMd) {
        // Desktop: navigate to details page
        BorrowNavigation.pushToBorrowReserveDetails(navigation, {
          networkId: market.networkId,
          provider: market.provider,
          marketAddress: market.marketAddress,
          reserveAddress: item.reserveAddress,
          symbol: item.token.symbol,
          logoURI: item.token.logoURI,
          accountId: accountId || undefined,
          indexedAccountId,
        });
      } else {
        // Mobile: block disabled supply assets (e.g. already borrowed)
        if (!noConnectedWalletRef.current && item.supplyButton?.disabled) {
          return;
        }
        handleManageSupply(item);
      }
    },
    [navigation, market, gtMd, handleManageSupply, accountId, indexedAccountId],
  );

  const showLoading =
    isBorrowReservesPending(borrowDataStatus) ||
    !hasBorrowReservesForMarket({
      data: reserves.data,
      ownerMarketKey: reserves.ownerMarketKey,
      marketKey: market ? buildBorrowMarketKey(market) : undefined,
    });

  // Per-row disabled state: dim + block tap for disabled supply assets on mobile.
  // Desktop rows navigate to details (still useful), so only mobile rows are disabled.
  // Uses noConnectedWalletRef to avoid stale closure from TableList memo.
  const getListItemProps = useCallback(
    (item: ISupplyAsset) => {
      if (gtMd) return undefined;
      if (noConnectedWalletRef.current) return undefined;
      return item.supplyButton?.disabled ? { disabled: true } : undefined;
    },
    [gtMd],
  );

  // Filter data based on showZeroBalance (mobile always shows all assets)
  const filteredAssets = useMemo(() => {
    const supportedAssets = filterUnsupportedAaveNativeReserveAssets({
      assets: reserves.data?.supply?.assets,
      networkId: market?.networkId,
      providerName: market?.provider,
    });
    // Mobile: always show all assets
    if (!gtMd) return supportedAssets;
    // Desktop: filter based on showZeroBalance toggle
    if (showZeroBalance) return supportedAssets;
    return supportedAssets.filter((asset) =>
      hasPositiveBorrowBalance(asset.walletBalance),
    );
  }, [
    gtMd,
    market?.networkId,
    market?.provider,
    reserves.data?.supply?.assets,
    showZeroBalance,
  ]);

  const { visibleAssets, foldedAssets } = useMemo(
    () =>
      splitCbbtcAssets({
        assets: filteredAssets,
        networkId: market?.networkId,
        providerName: market?.provider,
        marketAddress: market?.marketAddress,
      }),
    [
      filteredAssets,
      market?.marketAddress,
      market?.networkId,
      market?.provider,
    ],
  );
  const [showFoldedCbbtc, setShowFoldedCbbtc] = useState(false);
  const cbbtcAssetListKey = useMemo(
    () =>
      [
        accountId,
        market?.networkId,
        market?.provider,
        market?.marketAddress,
        ...visibleAssets.map((asset) => asset.reserveAddress),
        ...foldedAssets.map((asset) => asset.reserveAddress),
      ].join('|'),
    [
      accountId,
      foldedAssets,
      market?.marketAddress,
      market?.networkId,
      market?.provider,
      visibleAssets,
    ],
  );
  useEffect(() => {
    setShowFoldedCbbtc(false);
  }, [cbbtcAssetListKey]);

  const assetsToRender = showFoldedCbbtc
    ? [...visibleAssets, ...foldedAssets]
    : visibleAssets;

  const cbbtcMoreToggle = useMemo(
    () =>
      foldedAssets.length > 0 ? (
        <BorrowMoreToggle
          testID="borrow-supply-cbbtc-more-toggle"
          expanded={showFoldedCbbtc}
          onPress={() => setShowFoldedCbbtc((expanded) => !expanded)}
        />
      ) : null,
    [foldedAssets.length, showFoldedCbbtc],
  );

  const supplyListProps = useMemo(
    () => ({
      listItemProps: getListItemProps,
      ListFooterComponent: cbbtcMoreToggle,
    }),
    [cbbtcMoreToggle, getListItemProps],
  );

  const labels = useMemo(
    () => ({
      supplyApy: intl.formatMessage({ id: ETranslations.defi_supply_apy }),
      balance: intl.formatMessage({ id: ETranslations.global_balance }),
      supply: intl.formatMessage({ id: ETranslations.defi_supply }),
      assetCanBeCollateral: intl.formatMessage({
        id: ETranslations.global_asset,
      }),
      assetsToSupply: intl.formatMessage({
        id: ETranslations.defi_assets_to_supply,
      }),
      noAssetsToSupply: intl.formatMessage({
        id: ETranslations.defi_no_assets_to_supply,
      }),
      showAssetsWithZeroBalance: intl.formatMessage({
        id: ETranslations.defi_show_assets_with_0_balance,
      }),
    }),
    [intl],
  );

  const filterUI = useMemo(
    () => (
      <XStack ai="center" gap="$3">
        <Switch
          testID={BorrowTestIDs.supplyZeroBalanceSwitch}
          value={showZeroBalance}
          onChange={setShowZeroBalance}
          size="small"
        />
        <SizableText size="$bodyMd" color="$text">
          {labels.showAssetsWithZeroBalance}
        </SizableText>
      </XStack>
    ),
    [showZeroBalance, labels.showAssetsWithZeroBalance],
  );
  const showAdditionalActions = useMemo(
    () => gtLg && !noConnectedWallet && !accountNetworkNotSupported,
    [gtLg, noConnectedWallet, accountNetworkNotSupported],
  );

  // Mobile columns - 2 columns only
  const mobileColumns = useMemo(
    () => [
      {
        label: labels.assetCanBeCollateral,
        key: 'asset',
        render: (item: ISupplyAsset) => (
          <AssetWithAmountField
            token={item.token}
            canBeCollateral={item.canBeCollateral}
            amountLabel={{ text: `${labels.balance}:` }}
            amount={item.walletBalance.title}
            amountDescription={item.walletBalance.description}
            platformBonusApy={item.platformBonusApy}
          />
        ),
        flex: 1.5,
      },
      {
        label: labels.supplyApy,
        align: 'flex-end' as const,
        key: 'supplyApy',
        render: BorrowAPYField,
        flex: 1,
      },
    ],
    [labels],
  );

  // Desktop columns - all columns
  const desktopColumns = useMemo(
    () => [
      {
        // The collateral mark stays on the symbol, the way the mobile list
        // shows it — it labels the asset, not a value of its own.
        label: labels.assetCanBeCollateral,
        key: 'asset',
        render: (item: ISupplyAsset) => (
          <AssetField
            token={item.token}
            canBeCollateral={item.canBeCollateral}
            platformBonusApy={item.platformBonusApy}
          />
        ),
        flex: 1,
        minWidth: BORROW_TABLE_ASSET_COLUMN_MIN_WIDTH,
      },
      {
        label: labels.balance,
        align: 'flex-end' as const,
        key: 'balance',
        sortable: true,
        comparator: (a: ISupplyAsset, b: ISupplyAsset) => {
          const aFiatValue = new BigNumber(a.walletBalance?.fiatValue || '0');
          const bFiatValue = new BigNumber(b.walletBalance?.fiatValue || '0');
          return aFiatValue.comparedTo(bFiatValue);
        },
        render: (item: ISupplyAsset) => (
          <AmountField
            title={item.walletBalance.title}
            description={item.walletBalance.description}
          />
        ),
        flex: 1,
        minWidth: BORROW_TABLE_AMOUNT_COLUMN_MIN_WIDTH,
        maxWidth: BORROW_TABLE_AMOUNT_COLUMN_MAX_WIDTH,
      },
      {
        label: labels.supplyApy,
        align: 'flex-end' as const,
        key: 'supplyApy',
        render: BorrowAPYField,
        flex: 1,
        minWidth: BORROW_TABLE_APY_COLUMN_MIN_WIDTH,
        maxWidth: BORROW_TABLE_APY_COLUMN_MAX_WIDTH,
      },
      {
        label: '',
        align: 'flex-end' as const,
        key: 'actions',
        render: (item: ISupplyAsset) => (
          <ActionField
            actionLabel={labels.supply}
            item={item}
            onPress={() => handleManageSupply(item)}
            needAdditionButton={showAdditionalActions}
            accountId={accountId}
            walletId={walletId}
            indexedAccountId={indexedAccountId}
            disabled={noConnectedWallet ? false : item.supplyButton?.disabled}
          />
        ),
        flex: 0,
        minWidth: showAdditionalActions
          ? BORROW_TABLE_ACTION_COLUMN_WIDTH
          : BORROW_TABLE_ACTION_COLUMN_COMPACT_WIDTH,
      },
    ],
    [
      handleManageSupply,
      showAdditionalActions,
      noConnectedWallet,
      accountId,
      walletId,
      indexedAccountId,
      labels,
    ],
  );

  return (
    <Card title={labels.assetsToSupply} renderFilter={gtMd ? filterUI : null}>
      <BorrowTableList<ISupplyAsset>
        data={assetsToRender}
        isLoading={showLoading}
        columns={gtMd ? desktopColumns : mobileColumns}
        hideEmptyState={foldedAssets.length > 0}
        onPressRow={handlePressRow}
        emptyContent={labels.noAssetsToSupply}
        defaultSortKey="balance"
        defaultSortDirection="desc"
        listProps={supplyListProps}
      />
    </Card>
  );
};
